import {AbstractControl, ValidatorFn} from '@angular/forms';
import {IValidator} from '../../interface/validation/i-validator';
import { Util } from '../util/util';


export class ValidatorMinValue implements IValidator {

  public error: string|undefined = undefined;
  public hasError: boolean = false;

  private value?: number;

  constructor(
    private readonly minValue$: number
  ) {}

  validate(): any {
    this.hasError = false;
    if (Util.isDefined(this.value) && this.value < this.minValue$) {
      this.error = `Bitte wählen Sie einen Wert nach dem Startwert (${this.minValue$}).`
      this.hasError = true;
      return {invalidValue: true};
    } else {
      return null;
    }
  }

  validator(): ValidatorFn {
    return (input: AbstractControl) => {
      this.value = input.value;
      return this.validate();
    };
  }
}
