import {AbstractControl, ValidatorFn} from '@angular/forms';
import moment from 'moment';
import {IValidator} from '../../interface/validation/i-validator';

export class ValidatorDate implements IValidator {

    public static readonly DATE_FORMAT = 'DD.MM.YYYY';

    public error = 'Bitte geben Sie ein gültiges Datum ein';
    public hasError: boolean = false;
    private value: any;

    constructor() {}

    public validator(): ValidatorFn {
        return (input: AbstractControl) => {
          this.value = input.value;
          return this.validate();
        };
    }

    public validate(): any {
      this.hasError = false;
      if (!this.value) {
          return null;
      }
      if (moment.isMoment(this.value)) {
          if (moment(this.value, ValidatorDate.DATE_FORMAT, true).isValid()) {
              if (moment(this.value, ValidatorDate.DATE_FORMAT, true).year() >= 1900) {
                  this.hasError = false;
                  return null;
              } else {
                  return this._fail();
              }
          } else {
              return this._fail();
          }
      }
      return null;
    }

    private _fail(): object {
        this.hasError = true;
        return {invalidDate: true};
    }

}
