import {FormGroup} from '@angular/forms';
import _ from 'underscore';
import {IAccessableFormControl, IAccessableFormOptions} from '../../interface/validation/i-accessable-form-control';
import {Util} from '../../impl/util/util';
import { Subject, Observable } from 'rxjs';

export abstract class AccessableFormGroup<TFields, TModel extends object>
  implements IAccessableFormControl<AccessableFormGroup<TFields, TModel>, TModel> {

  public control!: FormGroup;
  private fields$!: TFields;
  private changed$: Subject<any> = new Subject();
  private fieldChanged$: Subject<IAccessableFieldChange> = new Subject();

  public initialize(
    fields: TFields
  ): void {
    this.control = new FormGroup(
      _.mapObject(fields as unknown as AccessableControls, (field: IAccessableFormControl<any, any>) => {
        return field.control;
      })
    );
    this.fields$ = fields;

    _.each(this.controls$, (field: IAccessableFormControl<any, any>, key: string) => {
      field.valueChanges.subscribe(() => {
        this.fieldChanged$.next({name: key, control: field} as IAccessableFieldChange);
      });
    });
  }

  public markAsUsed(opts?: IAccessableFormOptions): AccessableFormGroup<TFields, TModel> {
    _.each(this.controls$, (field: IAccessableFormControl<any, any>) => field.markAsUsed(opts) );
    this.control.markAsDirty(opts);
    this.control.markAsTouched(opts);
    return this;
  }

  public markAsUnused(opts?: IAccessableFormOptions): AccessableFormGroup<TFields, TModel> {
    _.each(this.controls$, (field: IAccessableFormControl<any, any>) => field.markAsUnused(opts) );
    this.control.markAsPristine(opts);
    this.control.markAsUntouched(opts);
    return this;
  }

  /**
   * `mrd-form-field` markiert ein Feld bei jedem valueChanges als dirty - auch beim Laden per reset() und bei
   * enable()/disable(). Nach dem programmatischen Befuellen gilt das Formular damit wieder als unveraendert;
   * `emitEvent: false`, damit die Neuvalidierung nicht erneut valueChanges und damit dirty ausloest.
   */
  public markAsUnchanged(): AccessableFormGroup<TFields, TModel> {
    return this.markAsUnused({ emitEvent: false });
  }

  /**
   * `mrd-form-field` zeigt Fehler erst nach valueChanges oder Touched/Blur des Feldes - beim Speichern
   * unberuehrter Felder also nicht. Zeigt die Fehler aller Felder an; dirty bleibt nur, wenn der Benutzer
   * wirklich etwas geaendert hat, sonst fragt ein Seitenwechsel grundlos nach.
   */
  public showErrors(): AccessableFormGroup<TFields, TModel> {
    const warGeaendert = this.dirty;
    this.markAsUsed();
    if (!warGeaendert) {
      this.control.markAsPristine();
    }
    return this;
  }

  public markAsDirty(opts?: IAccessableFormOptions): AccessableFormGroup<TFields, TModel> {
    _.each(this.controls$, (field: IAccessableFormControl<any, any>) => field.markAsDirty(opts) );
    this.control.markAsDirty(opts);
    return this;
  }

  public markAsTouched(opts?: IAccessableFormOptions): AccessableFormGroup<TFields, TModel> {
    _.each(this.controls$, (field: IAccessableFormControl<any, any>) => field.markAsTouched(opts) );
    this.control.markAsTouched(opts);
    return this;
  }

  public reset(model: TModel, propagateChanges: boolean = true): AccessableFormGroup<TFields, TModel> {
    if (!Util.isDefined(model)) {
      model = {} as TModel;
    }
    _.each(this.controls$, (field: IAccessableFormControl<any, any>, key: string) => field.reset((model as Record<string, any>)[key]));

    if (propagateChanges) {
      this.changed$.next(this.value);
    }
    return this;
  }

  get fields(): TFields {
    return this.fields$;
  }

  /** `TFields` ist generisch und fuer underscore nicht als Objekt erkennbar; vor `initialize()` leer. */
  private get controls$(): AccessableControls {
    return (this.fields$ ?? {}) as unknown as AccessableControls;
  }

  get value(): TModel {
    const ret: Record<string, any> = {};
    _.each(this.controls$, (field: IAccessableFormControl<any, any>, key: string) => ret[key] = field.value);
    return ret as TModel;
  }

  get rawValue(): any {
    const ret = {} as any;
    _.each(this.controls$, (field: IAccessableFormControl<any, any>, key: string) => ret[key] = field.rawValue);
    return ret;
  }

  get dirty(): boolean {
    return this.control.dirty;
  }

  get valid(): boolean {
    return this.control.valid;
  }

  get touched(): boolean {
    return this.control.touched;
  }

  disable(opts?: IAccessableFormOptions): AccessableFormGroup<TFields, TModel> {
    this.control.disable(opts);
    return this;
  }

  enable(opts?: IAccessableFormOptions): AccessableFormGroup<TFields, TModel> {
    this.control.enable(opts);
    return this;
  }

  get disabled(): boolean {
    return this.control.disabled;
  }

  get enabled(): boolean {
    return this.control.enabled;
  }

  get valueChanges(): Observable<void> {
    return this.changed$.asObservable();
  }

  get fieldChanges(): Observable<IAccessableFieldChange> {
    return this.fieldChanged$.asObservable();
  }
}

type AccessableControls = Record<string, IAccessableFormControl<any, any>>;

export interface IAccessableFieldChange {
  name: string;
  control: IAccessableFormControl<any, any>;
}