import _ from 'underscore';

export class Util {

  public static isDefined<T>(obj: T | null | undefined): obj is NonNullable<T> {
    return obj !== null && obj !== undefined;
  }

  /**
   * Prüft, ob ein Objekt definiert ist und nicht leer oder 0 ist.
   * Als nicht definiert gelten: null, undefined
   * Objekte, die als leer gelten, sind: {}
   * Strings, die als leer gelten, sind: ''
   * Arrays, die als leer gelten, sind: []
   * Zahlen, die als Zero gelten, sind: 0
   * 
   * @param obj Das zu prüfende Objekt
   * @param returnTheValueIfDefined Gibt an, ob der Wert zurückgegeben werden soll, wenn das Objekt definiert ist
   * @param undefinedReturnValue Der Wert, der zurückgegeben wird, wenn das Objekt nicht definiert ist und returnTheValueIfDefined auf true gesetzt ist
   * @returns Wenn returnTheValueIfDefined auf true gesetzt ist, wird der Wert des Objekts zurückgegeben, wenn es definiert ist oder undefinedRetrunValue (default: false). 
   * Ansonsten wird true zurückgegeben, wenn das Objekt definiert ist, ansonsten false.
   */
  public static isDefinedNotEmptyOrZero(obj: any, returnTheValueIfDefined: boolean = false, undefinedReturnValue: any = false): boolean|any {
    if (obj === null || obj === undefined) {
      return returnTheValueIfDefined ? undefinedReturnValue : false;
    }
    if (_.isString(obj) && obj === '') {
      return returnTheValueIfDefined ? undefinedReturnValue : false;
    }
    if (_.isArray(obj) && obj.length === 0) {
      return returnTheValueIfDefined ? undefinedReturnValue : false;
    }
    if (_.isNumber(obj) && !_.isNaN(obj) && obj === 0) {
      return returnTheValueIfDefined ? undefinedReturnValue : false;
    }
    if (_.isObject(obj) && _.isEmpty(obj)) {
      return returnTheValueIfDefined ? undefinedReturnValue : false;
    }
    return returnTheValueIfDefined ? obj : true;
  }

  public static armUrlWithSearchParams(url: string, queryParams?: object): string {
    if (!queryParams || _.isEmpty(queryParams)) {
      return url;
    }
    _.each(queryParams, (value: any, key: string) => {
      const querySelector = url.indexOf('?') === -1 ? '?' : '&';
      url = `${url}${querySelector}${key}=${value}`;
    });
    return url;
  }

  public static createEntityUrl(url: string, id: any): string {
    return `${url}/${id}`;
  }

  public static getBrowser(): string {
    const ua = navigator.userAgent;
    let tem;
    let M = ua.match(/(opera|chrome|safari|firefox|msie|trident(?=\/))\/?\s*(\d+)/i) || [];
    if (/trident/i.test(M[1])) {
      tem = /\brv[ :]+(\d+)/g.exec(ua) || [];
      return 'IE ' + (tem[1] || '');
    }
    if (M[1] === 'Chrome') {
      tem = ua.match(/\b(OPR|Edge)\/(\d+)/);
      if (tem != null) {
        return tem.slice(1).join(' ').replace('OPR', 'Opera');
      }
    }
    M = M[2] ? [M[1], M[2]] : [navigator.appName, navigator.appVersion, '-?'];
    tem = ua.match(/version\/(\d+)/i);
    if (tem != null) {
      M.splice(1, 1, tem[1]);
    }
    return M.join(' ');
  }

  public static getCurrentUnixTimestamp(): number {
    return Math.round((new Date()).getTime() / 1000);
  }

  public static guid(): string {
    const s4 = () => {
      return Math.floor((1 + Math.random()) * 0x10000)
        .toString(16)
        .substring(1);
    };
    return s4() + s4() + '-' + s4() + '-' + s4() + '-' + s4() + '-' + s4() + s4() + s4();
  }

  private static transformUmlaute(value: string): string {
    return value
      .replace('Ä', 'Ae')
      .replace('ä', 'ae')
      .replace('Ö', 'Oe')
      .replace('ö', 'oe')
      .replace('Ü', 'Ue')
      .replace('ü', 'ue');
  }

  public static sortAlpabetically<TListType extends Record<string, any>>(list: TListType[], attribute: string): TListType[] {
    const resultList = _.sortBy(list, (item: TListType) => this.transformUmlaute(item[attribute]).toUpperCase());
    return resultList;
  }

}
