import { IAccessableFormControl, IAccessableFormOptions } from '../../interface/validation/i-accessable-form-control';
import { FormArray } from '@angular/forms';
import _ from 'underscore';
import { Util } from '../../impl/util/util';
import { IValidator } from '../../interface/validation/i-validator';
import { ValidatorRequired } from '../../impl/validation/validator-required';
import { Observable } from 'rxjs';

export const Type = Function;
export interface Type<T> extends Function { new (...args: any[]): T; }

export abstract class AccessableFormArray<TModel>
  implements IAccessableFormControl<AccessableFormArray<TModel>, TModel[]> {

  private validators$: IValidator[] = [];
  public control!: FormArray<any>;
  public type!: Type<IAccessableFormControl<any, any>>;
  private required$: boolean = false;

  private entries$!: IAccessableFormControl<any, TModel>[];
  private previousEntries$!: IAccessableFormControl<any, TModel>[];

  private disabled$: boolean = false;
  private enabled$: boolean = true;

  public initialize(type: Type<IAccessableFormControl<any, any>>): void {
    this.control = new FormArray<any>([]);
    this.type = type;
    this.entries$ = [];
    this.previousEntries$ = [];
  }

  public push(entry: TModel, skipSetPreviousEntries: boolean = false, opts?: IAccessableFormOptions): IAccessableFormControl<any, TModel> {
    if (!skipSetPreviousEntries) {
      this.previousEntries$ = this.entries$.slice();
    }
    const item = this.generateFormEntry(entry);
    this.entries$.push(item);
    this.control.push(item.control, opts);
    if (this.disabled$) {
      item.disable();
    }
    return item;
  }

  public removeAt(index: number, skipSetPreviousEntries: boolean = false, opts?: IAccessableFormOptions): void {
    if (!skipSetPreviousEntries) {
      this.previousEntries$ = this.entries$.slice();
    }

    this.entries$ = _.reject(this.entries$, (e, round: number) => {
      return round === index;
    });
    this.control.removeAt(index, opts);
    let markAsUsed = false;
    for (const entry of this.entries$) {
      markAsUsed = markAsUsed || entry.dirty;
    }
    markAsUsed ? this.markAsUsed(opts) : this.markAsUnused(opts);
  }

  public validateWith(validators: IValidator[], opts?: IAccessableFormOptions): AccessableFormArray<TModel> {
    if (!Util.isDefined(validators)) {
      validators = [];
    }
    if (_.isArray(validators)) {
      this.validators$ = validators;
    }
    this.control.setValidators(_.map(validators, (v: IValidator) => v.validator()));
    this.required$ = false;
    _.each(this.validators$, (v: IValidator) => {
      if (v instanceof ValidatorRequired) {
        this.required$ = true;
      }
    });
    this.control.updateValueAndValidity(opts);
    return this;
  }

  public clearValidators(): void {
    this.validators$ = [];
  }

  public generateFormEntry(value: any): IAccessableFormControl<any, TModel> {
    const validation = new this.type();
    validation.reset(value);
    return validation;
  }

  public get errors(): string[] {
    return _.compact(_.map(this.validators$, (e: IValidator) => {
      if (e.hasError) {
        return e.error;
      }
      return null;
    }));
  }

  public get error(): IValidator|undefined {
    return _.find(this.validators$, (v) => {
      return v.hasError;
    });
  }

  public get validators(): IValidator[] {
    return this.validators$;
  }

  get required(): boolean {
    return this.required$;
  }

  get dirty(): boolean {
    return this.control.dirty;
  }

  get touched(): boolean {
    return this.control.touched;
  }

  get valid(): boolean {
    return this.control.valid;
  }

  get value(): TModel[] {
    const ret: TModel[] = [];
    for (const entry of this.entries$) {
      ret.push(entry.value);
    }
    return ret;
  }

  get rawValue(): TModel[] {
    const ret: TModel[] = [];
    for (const entry of this.entries$) {
      ret.push(entry.rawValue);
    }
    return ret;
  }

  get entries(): IAccessableFormControl<any, TModel>[] {
    return this.entries$;
  }

  get previousEntries(): IAccessableFormControl<any, TModel>[] {
    return this.previousEntries$;
  }

  
  get valueChanges(): Observable<any> {
    return this.control.valueChanges;
  }

  get disabled(): boolean {
    return this.disabled$;
  }

  get enabled(): boolean {
    return this.enabled$;
  }

  get controlDisabled(): boolean {
    return this.control.disabled;
  }

  get controlEnabled(): boolean {
    return this.control.enabled;
  }

  public controlDisable(opts?: IAccessableFormOptions): AccessableFormArray<TModel> {
    this.control.disable(opts);
    return this;
  }

  public controlEnable(opts?: IAccessableFormOptions): AccessableFormArray<TModel> {
    this.control.enable(opts);
    if (!opts || opts?.onlySelf !== true) {
      for (const entry of this.entries$) {
        entry.enable();
      }
    }
    return this;
  }

  public disable(opts?: IAccessableFormOptions): AccessableFormArray<TModel> {
    this.disabled$ = true;
    this.enabled$ = false;
    // this.control.disable(opts);
    if (!opts || opts?.onlySelf !== true) {
      for (const entry of this.entries$) {
        entry.disable();
      }
    }
    return this;
  }

  public enable(opts?: IAccessableFormOptions): AccessableFormArray<TModel> {
    this.disabled$ = false;
    this.enabled$ = true;
    // this.control.enable(opts);
    if (!opts || opts?.onlySelf !== true) {
      for (const entry of this.entries$) {
        entry.enable();
      }
    }
    return this;
  }

  public markAsDirty(opts?: IAccessableFormOptions): AccessableFormArray<TModel> {
    if (!opts || opts?.onlySelf !== true) {
      for (const entry of this.entries$) {
        entry.markAsDirty();
      }
    }
    this.control.markAsDirty(opts);
    return this;
  }

  public markAsTouched(opts?: IAccessableFormOptions): AccessableFormArray<TModel> {
    if (!opts || opts?.onlySelf !== true) {
      for (const entry of this.entries$) {
        entry.markAsTouched();
      }
    }
    this.control.markAsTouched(opts);
    return this;
  }

  public markAsUnused(opts?: IAccessableFormOptions): AccessableFormArray<TModel> {
    if (!opts || opts?.onlySelf !== true) {
      for (const entry of this.entries$) {
        entry.markAsUnused();
      }
    }
    this.control.markAsUntouched(opts);
    this.control.markAsPristine(opts);
    return this;
  }

  public markAsUsed(opts?: IAccessableFormOptions): AccessableFormArray<TModel> {
    if (!opts || opts?.onlySelf !== true) {
      for (const entry of this.entries$) {
        entry.markAsUsed();
      }
    }
    this.control.markAsTouched(opts);
    this.control.markAsDirty(opts);
    return this;
  }

  public reset(models: TModel[], skipSetPreviousEntries: boolean = false): AccessableFormArray<TModel> {
    if (!skipSetPreviousEntries) {
      this.previousEntries$ = this.entries$.slice();
    }

    this.entries$ = [];
    this.control.clear();
    if (Util.isDefined(models) && _.isArray(models)) {
      for (const model of models) {
        this.push(model);
      }
    }
    if (this.disabled$) {
      this.disable();
    }

    return this;
  }

}
