import {AbstractControl, ValidatorFn} from '@angular/forms';
import _ from 'underscore';
import {IValidator} from '../../interface/validation/i-validator';

/** Prueft, ob eine Liste mindestens `minSize` Elemente enthaelt. */
export class ValidatorListLength implements IValidator {

  public static readonly ERROR_EMPTY = 'Das Feld muss mindestens __MIN_SIZE__ Element(e) enthalten.';

  public error?: string;
  public hasError: boolean = false;
  private value?: Array<any>;

  constructor(public minSize: number, private customError?: string) {}

  public validator(): ValidatorFn {
    return (input: AbstractControl): object | null => {
      this.value = input.value;
      return this.validate();
    };
  }

  public validate(): any {
    this.hasError = false;
    if (this.value === null || this.value === undefined || !_.isArray(this.value)) {
      return null;
    }
    if (this.value.length < this.minSize) {
      this.hasError = true;
      this.error = this.customError ?? ValidatorListLength.ERROR_EMPTY.replace('__MIN_SIZE__', this.minSize.toString());
      return {invalidMinSize: true};
    }
    return null;
  }

}
