import { EnvironmentInjector, inject, runInInjectionContext } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivateFn, RouterStateSnapshot, UrlTree } from '@angular/router';
import { Observable, Subscriber, forkJoin, from, isObservable } from 'rxjs';
import _ from 'underscore';
import {Util} from "../../impl/util/util";
import {SubscriptionManager} from "../../impl/util/subscription-manager";
import {SubscriptionHandler} from "../../impl/util/subscription-handler";
import {ActivationGuardStep, ActivationGuardResult, IActivationGuard} from "../../interface/routing/i-activation-guard";

/**
 * Fuehrt Guards schrittweise aus: die Guards eines Schritts parallel, die Schritte nacheinander. Schlaegt ein
 * Guard fehl, laufen die folgenden Schritte nicht mehr. In Routen als Klasse oder ueber
 * `mapToCanActivate([...])` aus `@angular/router` verwendbar.
 */
export abstract class AbstractActivationQueuedGuard implements IActivationGuard {

  private readonly queue: ActivationGuardStep[][] = [];
  private readonly injector: EnvironmentInjector | null = AbstractActivationQueuedGuard.currentInjector();

  public canActivate(
    route: ActivatedRouteSnapshot,
    state: RouterStateSnapshot
  ): ActivationGuardResult {
    return new Observable((subscriber) => {
      this.runQueueRecursive(0, route, state, subscriber);
    });
  }

  protected sequence(step: ActivationGuardStep[] | ActivationGuardStep): AbstractActivationQueuedGuard {
    this.queue.push(_.isArray(step) ? step as ActivationGuardStep[] : [step as ActivationGuardStep]);
    return this;
  }

  /** Nur ein per DI erzeugter Guard kennt seinen Injector; funktionale Schritte brauchen ihn. */
  private static currentInjector(): EnvironmentInjector | null {
    try {
      return inject(EnvironmentInjector);
    } catch {
      return null;
    }
  }

  private runQueueRecursive(
    level: number,
    route: ActivatedRouteSnapshot,
    state: RouterStateSnapshot,
    subscriber: Subscriber<boolean | UrlTree>
  ): void {
    const currentQueueItems: ActivationGuardStep[] = this.queue[level];
    if (!Util.isDefined(currentQueueItems)) {
      subscriber.next(true);
      subscriber.complete();
      return;
    }
    const activators: Observable<boolean | UrlTree>[] = _.map(currentQueueItems, (step: ActivationGuardStep) => {
      return this.asObservable(this.runStep(step, route, state));
    });
    SubscriptionManager.subscribe(forkJoin(activators), new SubscriptionHandler(
      (canActivateStates: (boolean | UrlTree)[]) => {
        if (!_.all(canActivateStates)) {
          subscriber.next(false);
          subscriber.complete();
        } else {
          this.runQueueRecursive(level + 1, route, state, subscriber);
        }
      },
      () => {
        subscriber.next(false);
        subscriber.complete();
      }
    ));
  }

  private runStep(step: ActivationGuardStep, route: ActivatedRouteSnapshot, state: RouterStateSnapshot): ActivationGuardResult {
    if (typeof step !== 'function') {
      return step.canActivate(route, state);
    }
    if (!this.injector) {
      throw new Error('AbstractActivationQueuedGuard: funktionale Guards brauchen einen per DI erzeugten Guard.');
    }
    return runInInjectionContext(this.injector, () => (step as CanActivateFn)(route, state));
  }

  /** forkJoin braucht Observables; synchrone und Promise-Ergebnisse eines Guards werden daher umgewandelt. */
  private asObservable(result: ActivationGuardResult): Observable<boolean | UrlTree> {
    return isObservable(result) ? result : from(Promise.resolve(result));
  }

}
